def test_amount_parser_preserves_integer_cents_and_rejects_precision() -> None:
    assert amount_cents("12") == 1200
    assert amount_cents("-0.05") == -5
    for value in ("0", "1.234", "1.", "x"):
        try:
            amount_cents(value)
        except ValidationError:
            pass
        else:
            raise AssertionError(value)


